('advanced-native-183', '["phrase"]'::jsonb, '{"advanced-native-183-v1-audio":{"type":"mc","answers":["Emotional comfort and company without removing every responsibility."],"options":["Only practical arrangements are exchanged, with no emotional closeness described.","The visits take place only at rare formal occasions rather than in ordinary weeks.","Only the time of the visit changes, while the sense of company remains absent.","Emotional comfort and company without removing every responsibility."]},"advanced-native-183-v2-reply":{"type":"mc","answers":["The friendly routine helps me feel connected.","I enjoy the care and company without needing a special occasion.","We share stories and make time for one another.","It brings warmth, affection, and companionship into everyday life."],"options":["The friendly routine helps me feel connected.","I enjoy the care and company without needing a special occasion.","We share stories and make time for one another.","It brings warmth, affection, and companionship into everyday life."]},"advanced-native-183-v1-scene":{"type":"mc","answers":["These moments bring warmth, affection, and companionship into everyday life."],"options":["The family saves all its contact for special formal occasions instead of ordinary days.","These moments bring warmth, affection, and companionship into everyday life.","These moments are only for exchanging household schedules, without care or closeness."]},"advanced-native-183-v1-contrast":{"type":"mc","answers":["Receiving companionship guarantees that all difficulties disappear."],"options":["Receiving companionship guarantees that all difficulties disappear.","Ordinary routines can include emotional closeness.","Care and company can make daily life feel warmer."]},"advanced-native-183-v1-branch":{"type":"mc","answers":["Pets can bring warmth, affection, and companionship into everyday life, but their needs still require time and care."],"options":["Pets can bring warmth, affection, and compani